// naive occurrence count
int countNaive(string t, string p){
    int c = 0;
    for (int i = 0; i + p.size() <= t.size(); i++) {
        bool ok = true;
        for (int j = 0; j < p.size(); j++)
            if (t[i+j] != p[j]) { ok = false; break; }
        c += ok;
    }
    return c;   // O(n*m) — dies on adversarial inputs
}

